window.Review211={load:src=>new Promise((yes,no)=>{const s=document.createElement('script');s.src=src;s.onload=yes;s.onerror=()=>no(Error(src));document.body.append(s);}),ready:(async()=>{const d=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const e of d.querySelectorAll('script[src]')){const src=e.getAttribute('src');if(src.startsWith('game.js')||src.includes('-ui'))continue;await new Promise((yes,no)=>{const s=document.createElement('script');s.src=src;s.onload=yes;s.onerror=()=>no(Error(src));document.body.append(s);});}})()};
